def reserve(stock, location, lines):
    """Reserve ``lines`` as ``(item, units)`` pairs at ``location``.

    All or nothing: if the location cannot cover every line (repeated items added up first), ValueError
    ``not enough <item> at <location>`` is raised for the first short item in name order and the stock is
    left as it was. On success the units are removed from that location only.
    """
    wanted = {}
    for item, units in lines:
        wanted[item] = wanted.get(item, 0) + units
    for item in sorted(wanted):
        if stock[location].get(item, 0) < wanted[item]:
            raise ValueError(f"not enough {item} at {location}")
    for item in sorted(wanted):
        stock[location][item] -= wanted[item]
    return stock

